+
+export async function callTool(name, args = {}) {
+  switch (name) {
+    case 'open_client': {
+      const { client_id } = args;
+      requireNonEmptyString(client_id, 'client_id');
+      if (!clients.has(client_id)) {
+        clients.set(client_id, new Map());
+      }
+      return { content: [{ type: 'text', text: JSON.stringify({ client_id, opened: true }) }] };
+    }
+    case 'client_put': {
+      const { client_id, key, value } = args;
+      requireClient(client_id);
+      requireNonEmptyString(key, 'key');
+      requireNonEmptyString(value, 'value');
+      clients.get(client_id).set(key, value);
+      return { content: [{ type: 'text', text: JSON.stringify({ client_id, key, stored: true }) }] };
+    }
+    case 'client_get': {
+      const { client_id, key } = args;
+      requireClient(client_id);
+      requireNonEmptyString(key, 'key');
+      const store = clients.get(client_id);
+      if (!store.has(key)) {
+        const error = new Error(`unknown key: ${key}`);
+        error.code = -32602;
+        throw error;
+      }
+      const value = store.get(key);
+      return { content: [{ type: 'text', text: JSON.stringify({ client_id, key, value }) }] };
+    }
+    default: {
+      const error = new Error(`unknown tool: ${name}`);
+      error.code = -32601;
+      throw error;
+    }
+  }
